function clue(title,copy,stopId,sourceList=[]){const card=document.createElement('section');card.className='clue-card';const tag=document.createElement('span');tag.className='step';tag.textContent=conversationMode==='demo'?'示例线索 · 待核查':'公开资料线索';const heading=document.createElement('h2');heading.textContent=title;const p=document.createElement('p');p.textContent=copy;card.append(tag,heading,p);if(stopId&&stops.some(s=>s.id===stopId)){const button=document.createElement('button');button.type='button';button.className='text-button';button.textContent='在地图上查看';const snapshot=stops.find(s=>s.id===stopId);button.addEventListener('click',()=>{if(!stops.includes(snapshot)){window.routeRevealed=false;setMapDataset([snapshot],[]);$('map-heading').textContent='回看这条线索';$('route-caption').textContent='前一轮查询中的地点 · 非最新查询全图';}selectStop(snapshot.id);});card.append(button);}const details=document.createElement('details');const summary=document.createElement('summary');summary.textContent='查看依据';const body=document.createElement('div');if(sourceList.length){for(const source of sourceList)linkSource(body,source);}else{const text=document.createElement('p');text.textContent=stops.find(s=>s.id===stopId)?.source||'位置尚不明确，暂不在地图上定位。';body.append(text);}details.append(summary,body);card.append(details);$('conversation').append(card);scrollThread();}
