async function submitQuestion(text){if(typeof text!=='string'||!text.trim()||text.length>600){$('form-error').textContent='写一点你想了解的问题，再开始探索。';$('form-error').hidden=false;return {status:'invalid'};}if(busy)return {status:'busy'};text=text.trim();$('form-error').hidden=true;if(conversationMode==='live')return sendResearch(text);message('user',text);const negative=/不姓阮|不是阮|并非阮|姓[陈张李王刘赵黄杨吴周徐孙马朱胡郭何林高郑]/.test(text);if(query?.demo&&!negative&&['generation','candidate'].includes(conversationStage)&&/英.?士.?班|班.?家.?国/.test(text)){$('conversation').lastElementChild.remove();act('dayuan',text);}else if(query?.demo&&!negative&&['generation','candidate'].includes(conversationStage)&&/英.?士.?中|中.?州.?启/.test(text)){$('conversation').lastElementChild.remove();act('yangxin',text);}else if(query?.demo&&conversationStage==='generation'&&/^(暂时)?(不知道|不记得|不清楚)/.test(text)){$('conversation').lastElementChild.remove();act('unknown',text);}else if(query?.demo&&!negative&&/江西|迁徙|迁来|乐平/.test(text)){$('conversation').lastElementChild.remove();act('route',text);}else if(query?.demo&&!negative&&/阮籍|竹林|堂号/.test(text)){$('conversation').lastElementChild.remove();act('culture',text);}else{message('assistant','当前是阮氏固定示例，不能用它判断你家的来历。可以选择下方示例体验流程，或切换「真实溯源」查询自己的线索。');if(negative){query=null;branch=null;conversationStage='welcome';useDemoMap();}welcomeSuggestions();}setBusy(false);return {stage:conversationStage,demoOnly:true};}
$('chat-form').addEventListener('submit',e=>{e.preventDefault();if(busy)return;const text=$('question').value;if(!text.trim()){submitQuestion(text);return;}submitQuestion(text);if((!busy||conversationMode==='live')&&(conversationMode!=='live'||Date.now()>=researchRetryAt)){$('question').value='';$('question').style.height='';}});$('question').addEventListener('input',()=>{$('form-error').hidden=true;$('question').style.height='auto';$('question').style.height=Math.min($('question').scrollHeight,160)+'px';});$('question').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing&&!e.ctrlKey&&!e.metaKey){e.preventDefault();$('chat-form').requestSubmit();}});$('reset-chat').addEventListener('click',resetConversation);$('cancel-query').addEventListener('click',()=>cancelResearch());$('mode-demo').addEventListener('click',()=>switchMode('demo'));$('mode-live').addEventListener('click',()=>switchMode('live'));
