if(document.modelContext?.registerTool){const lifecycle=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'ask_family_history',description:'向当前选择的模式提问；真实模式通过服务端检索，示例模式使用预置材料。',inputSchema:{type:'object',properties:{question:{type:'string',minLength:1,maxLength:600}},required:['question'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:input=>submitQuestion(input?.question)},{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
